#!/usr/bin/env python3
"""l3_bank_check.py --bank DIR --expect-windows N --ue-sha HEX [--allow-partial] [--out PATH]  -- the SEED3 bank's own check (card PREREG_V8F_SEED3 section 2 and the lever-acts list), after the stock `rh_pilot_check.py bank` passed. stdlib only, CPU, sub-second.
Reads DIR/bank.json and DIR/BANK_CHECK.json and requires:
  * BANK_CHECK.json (the stock full-bank check, readout causal_g1x) is a pass;
  * the bank's generator record NAMES UE_sK.A: `common.ckpt_sha256` == the pinned sha256 (6d434525..., K-B2: the trainer refuses a bank not generated by the arm's own init);
  * `common.generator` == {readout causal_g, acc_gain 1.0, path_exec true, kappa_max "0.2"} (readout causal_g1x, as the s0 and s1 banks);
  * coverage fraction >= 0.5 and not blocked; the bank is complete (`partial` false) with `common.train.n_windows` == the expected window count.
Writes DIR/L3_BANK_CHECK.json (`pass`, `generator_ckpt_sha256`, `coverage_fraction`, `partial`, ...). Last line `ZZ L3-BANK-CHECK PASS|FAIL`."""
import argparse
import hashlib
import json
import os
import sys

WANT_GEN = {"readout": "causal_g", "acc_gain": 1.0, "path_exec": True, "kappa_max": "0.2"}


def check(bank_dir, expect_windows, ue_sha, allow_partial=False):
    bad, rep = [], {}
    bj, bc = f"{bank_dir}/bank.json", f"{bank_dir}/BANK_CHECK.json"
    for p in (bj, bc):
        if not os.path.isfile(p):
            bad.append(f"missing {p}")
    if bad:
        return bad, rep
    b = json.load(open(bj))
    c = json.load(open(bc))
    com = b.get("common", {})
    rep.update({"bank_json_sha256": hashlib.sha256(open(bj, "rb").read()).hexdigest(), "generator_ckpt_sha256": com.get("ckpt_sha256"), "generator": com.get("generator"),
                "partial": com.get("partial", b.get("partial")), "n_windows": (com.get("train") or {}).get("n_windows"), "expect_windows": expect_windows,
                "bank_check_pass": c.get("pass"), "bank_check_readout": c.get("readout")})
    c_ok = c.get("pass") is True or (allow_partial and all(v.get("pass") for k, v in (c.get("checks") or {}).items() if not k.startswith("e_")))   # a smoke bank fails only check e (complete cover)
    if not c_ok or c.get("readout") != "causal_g1x":
        bad.append(f"BANK_CHECK.json pass={c.get('pass')} readout={c.get('readout')!r}: the stock full-bank check did not pass for causal_g1x")
    if com.get("ckpt_sha256") != ue_sha:
        bad.append(f"the bank's generator record names ckpt {str(com.get('ckpt_sha256'))[:12]}, not UE_sK.A {ue_sha[:12]} (K-B2)")
    if com.get("generator") != WANT_GEN:
        bad.append(f"the bank's generator is {com.get('generator')}, expected {WANT_GEN}")
    cov = b.get("coverage") or {}
    rep["coverage_fraction"] = cov.get("fraction")
    if not isinstance(cov.get("fraction"), (int, float)) or isinstance(cov.get("fraction"), bool) or cov["fraction"] < 0.5 or cov.get("blocked") is not False:
        bad.append(f"coverage {cov.get('fraction')!r} blocked={cov.get('blocked')!r}: below 0.5 or blocked (BLOCKED, the card's lever-acts list)")
    if rep["partial"] is not False and not allow_partial:
        bad.append(f"the bank is partial ({rep['partial']!r})")
    if not expect_windows or rep["n_windows"] != expect_windows:
        bad.append(f"train n_windows {rep['n_windows']} != expected {expect_windows}")
    return bad, rep


def main(argv=None):
    ap = argparse.ArgumentParser()
    ap.add_argument("--bank", required=True)
    ap.add_argument("--expect-windows", type=int, required=True)
    ap.add_argument("--ue-sha", required=True)
    ap.add_argument("--allow-partial", action="store_true", help="smoke banks only (--limit-clips): the partial flag is not a problem; the report says partial")
    ap.add_argument("--out", default=None)
    a = ap.parse_args(argv)
    bad, rep = check(a.bank, a.expect_windows, a.ue_sha, a.allow_partial)
    rep["pass"] = not bad
    rep["problems"] = bad
    if a.out and os.path.isdir(os.path.dirname(os.path.abspath(a.out))):
        json.dump(rep, open(a.out, "w"), indent=1)
    for m in bad:
        print("PROBLEM", m)
    print(json.dumps({k: rep.get(k) for k in ("generator_ckpt_sha256", "coverage_fraction", "partial", "n_windows")}))
    print("ZZ L3-BANK-CHECK", "PASS" if not bad else "FAIL")
    return 0 if not bad else 1


if __name__ == "__main__":
    sys.exit(main())
